card('m1').querySelector('.message-translate-action').click();await wait(()=>window.__calls.length===1&&card('m1').querySelector('.inline-translation')?.dataset.status==='complete','English translation appears inline');assert(window.__calls[0].messages[1].content===s.messages.find(m=>m.id==='m1').text,'translation submits only source text');
